<script setup lang="ts">
const {state,select}=useProjectKabanNavigation()
const emit=defineEmits<{navigate:[]}>()
const views=[{value:'board',label:'Доска задач',icon:'i-lucide-columns-3'},{value:'closed',label:'Закрытые задачи',icon:'i-lucide-archive'},{value:'history',label:'История изменений',icon:'i-lucide-history'},{value:'categories',label:'Категории',icon:'i-lucide-folder-tree'}] as const
function choose(value:typeof views[number]['value'],category='all',mine=false,overdue=false){select(value,category,mine,overdue);emit('navigate')}
</script>
<template><nav class="board-navigation" aria-label="Кабан проекта"><p>КАБАН</p><button v-for="item in views" :key="item.value" :aria-current="state.view===item.value&&!state.onlyMine&&!state.onlyOverdue&&state.selectedCategory==='all'?'page':undefined" @click="choose(item.value)"><UIcon :name="item.icon"/>{{item.label}}</button><button :aria-current="state.onlyMine?'page':undefined" @click="choose('board','all',true)"><UIcon name="i-lucide-user-round-check"/>Мои задачи</button><button :aria-current="state.onlyOverdue?'page':undefined" @click="choose('board','all',false,true)"><UIcon name="i-lucide-clock-alert"/>Просроченные</button><div class="board-categories-heading"><button @click="choose('categories')">КАТЕГОРИИ</button><UButton v-if="state.canEdit" icon="i-lucide-plus" color="neutral" variant="ghost" aria-label="Добавить категорию" @click="state.createCategory++;emit('navigate')"/></div><button v-for="category in state.categories" :key="category.id" :class="{'is-child':category.parentId}" :aria-current="state.selectedCategory===category.id?'page':undefined" :title="category.name" @click="choose('board',category.id)"><span class="category-dot" :style="{background:category.color}"/><span class="category-name">{{category.name}}</span><small>{{category.count}}</small></button><button v-if="state.canEdit" @click="state.createCategory++;emit('navigate')"><UIcon name="i-lucide-folder-plus"/>Добавить категорию</button></nav></template>
<style scoped>
.board-navigation{display:grid;gap:5px;padding-top:22px;border-top:1px solid #e8edf3}.board-navigation>p,.board-categories-heading>button{font-size:10px;letter-spacing:1.4px;color:#94a3b8;padding:0 12px;margin-bottom:8px}.board-navigation>button{display:flex;align-items:center;gap:10px;padding:12px;border-radius:10px;text-align:left;color:#8292a8;font-size:13px}.board-navigation>button:hover,.board-navigation>button[aria-current=page]{background:#f1f3f8;color:var(--ui-primary)}.board-navigation .iconify{width:18px;height:18px;flex-shrink:0}.board-categories-heading{display:flex;align-items:center;justify-content:space-between;margin-top:24px}.board-categories-heading>button{margin:0}.category-dot{width:8px;height:8px;border-radius:50%;flex-shrink:0}.category-name{flex:1;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.board-navigation>button.is-child{margin-left:14px;border-left:1px solid #e2e8f0;border-radius:0 10px 10px 0}.board-navigation small{font-size:11px}
</style>
